effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat6;
uint u_xlatu6;
vec2 u_xlat12;
float u_xlat18;
float u_xlat19;
void main()
{
    u_xlat0.x = acScreenNorm.y * 2.0 + -1.0;
    u_xlat0.x = u_xlat0.x + (-_offset);
    u_xlat6.x = float(_band_count);
    u_xlat12.x = u_xlat6.x * acScreenNorm.x;
    u_xlat18 = floor(u_xlat12.x);
    u_xlat12.x = fract(u_xlat12.x);
    u_xlat6.x = u_xlat6.x * 0.0322580636;
    u_xlat6.x = u_xlat18 / u_xlat6.x;
    u_xlat6.x = max(u_xlat6.x, 0.0);
    u_xlat6.x = min(u_xlat6.x, 30.0);
    u_xlatu6 = uint(u_xlat6.x);
    u_xlat18 = 3.0 * _bands[int(u_xlatu6)];
    u_xlat18 = clamp(u_xlat18, 0.0, 1.0);
    u_xlat1.xyz = (-_color1.xyz) + _color2.xyz;
    u_xlat1.xyz = vec3(u_xlat18) * u_xlat1.xyz + _color1.xyz;
    u_xlat2.xy = vec2(-0.333333343, -0.666666687) + vec2(_bands[int(u_xlatu6)]);
    u_xlat2.xy = u_xlat2.xy * vec2(3.0, 3.0);
    u_xlat2.xy = clamp(u_xlat2.xy, 0.0, 1.0);
    u_xlat3.xyz = (-u_xlat1.xyz) + _color3.xyz;
    u_xlat1.xyz = u_xlat2.xxx * u_xlat3.xyz + u_xlat1.xyz;
    u_xlat2.xzw = (-u_xlat1.xyz) + _color4.xyz;
    u_xlat1.xyz = u_xlat2.yyy * u_xlat2.xzw + u_xlat1.xyz;
    u_xlat2 = (int(_invert) != 0) ? vec4(-1.0, -0.00999999978, -100.0, 100.0) : vec4(1.0, 0.00999999978, 100.0, -100.0);
    u_xlat6.xz = vec2(_scale.x, _scale.y) * vec2(_bands[int(u_xlatu6)]);
    u_xlat6.xz = u_xlat2.xx * u_xlat6.xz;
    u_xlat6.x = (-u_xlat6.x) * 1.5 + u_xlat0.x;
    u_xlat6.x = u_xlat2.z * u_xlat6.x;
    u_xlat6.x = clamp(u_xlat6.x, 0.0, 1.0);
    u_xlat19 = u_xlat6.x * -2.0 + 3.0;
    u_xlat6.x = u_xlat6.x * u_xlat6.x;
    u_xlat3.w = (-u_xlat19) * u_xlat6.x + 1.0;
    u_xlat3.xyz = u_xlat1.xyz * u_xlat3.www;
    u_xlat6.x = u_xlat6.z * 1.5 + u_xlat0.x;
    u_xlat6.x = u_xlat2.w * u_xlat6.x;
    u_xlat6.x = clamp(u_xlat6.x, 0.0, 1.0);
    u_xlat18 = u_xlat6.x * -2.0 + 3.0;
    u_xlat6.x = u_xlat6.x * u_xlat6.x;
    u_xlat4.w = (-u_xlat18) * u_xlat6.x + 1.0;
    u_xlat6.xz = (int(_invert) != 0) ? vec2(-0.5, -50.0) : vec2(0.5, 50.0);
    u_xlat6.x = u_xlat6.x + u_xlat0.x;
    u_xlat6.x = u_xlat2.x * u_xlat6.x;
    u_xlat6.x = clamp(u_xlat6.x, 0.0, 1.0);
    u_xlat19 = u_xlat6.x * -2.0 + 3.0;
    u_xlat6.x = u_xlat6.x * u_xlat6.x;
    u_xlat6.x = u_xlat6.x * u_xlat19;
    u_xlat1.xyz = u_xlat6.xxx * u_xlat1.xyz;
    u_xlat4.xyz = u_xlat1.xyz * u_xlat4.www;
    u_xlat0.x = u_xlat0.x + u_xlat2.y;
    u_xlat0.x = u_xlat6.z * u_xlat0.x;
    u_xlat0.x = clamp(u_xlat0.x, 0.0, 1.0);
    u_xlat6.x = u_xlat0.x * -2.0 + 3.0;
    u_xlat0.x = u_xlat0.x * u_xlat0.x;
    u_xlat0.x = u_xlat0.x * u_xlat6.x;
    u_xlat1 = u_xlat3 + (-u_xlat4);
    u_xlat1 = u_xlat0.xxxx * u_xlat1 + u_xlat4;
    u_xlat0.xy = u_xlat12.xx + vec2(-0.125, -0.875);
    u_xlat0.xy = u_xlat0.xy * vec2(4.0, -4.0);
    u_xlat0.xy = clamp(u_xlat0.xy, 0.0, 1.0);
    u_xlat12.xy = u_xlat0.xy * vec2(-2.0, -2.0) + vec2(3.0, 3.0);
    u_xlat0.xy = u_xlat0.xy * u_xlat0.xy;
    u_xlat0.xy = u_xlat0.xy * u_xlat12.xy;
    u_xlat1 = u_xlat0.xxxx * u_xlat1;
    u_xlat0 = u_xlat0.yyyy * u_xlat1;
    u_xlat0 = clamp(u_xlat0, 0.0, 1.0);
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlatb2.x = _blend_mode==1;
    u_xlat3 = u_xlat0 * u_xlat1;
    u_xlat4.xyz = u_xlat0.xyz + u_xlat1.xyz;
    u_xlat4.w = u_xlat1.w;
    u_xlat2 = (u_xlatb2.x) ? u_xlat3 : u_xlat4;
    u_xlat3.xyz = u_xlat0.xyz;
    u_xlat0 = (_blend_mode != 0) ? u_xlat2 : u_xlat3;
    if(_use_inner_mask != 0) {
        u_xlatb2.xy = equal(ivec4(_show_inner_mask, _b_clip_mask, _show_inner_mask, _show_inner_mask), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
